def maximum_bounded_jumps(nums,target):
    dp=[-10**9]*len(nums);dp[0]=0
    for end in range(1,len(nums)):
        for start in range(end):
            if abs(nums[end]-nums[start])<=target:dp[end]=max(dp[end],dp[start]+1)
    return -1 if dp[-1]<0 else dp[-1]

